module.exports = {
 "commit": "f4587b5",
 "portfolioWallet": "(function initWalletFetch() {\n\n const ALCHEMY_KEY = 'R_9y5DBqKNR2NapexG8n7';\n const HELIUS_KEY = '76a7f1e6-fac9-4361-a6bb-f7787926c719';\n\n const ETH_RPC = `https://eth-mainnet.g.alchemy.com/v2/${ALCHEMY_KEY}`;\n const BASE_RPC = 'https://mainnet.base.org'; // RPC público — a key Alchemy não tem Base habilitada\n const HELIUS_RPC= `https://mainnet.helius-rpc.com/?api-key=${HELIUS_KEY}`;\n const HELIUS_API= `https://api.helius.xyz/v0`;\n\n // ── Wallets ──────────────────────────────────────────────────────\n const EVM_WALLETS = [\n '0x5Ff957C19A03aF57B5098F3F395A578E394aE4B6',\n '0x5a9aaA78B379ec19beb9E44CCe12697d1894f396', // AAVE\n '0x835a5F686c489023064Edb0EA3A0f4ee54BD77F6',\n '0x8311038D68039f4C3e7237D64f4F2c598fBf4ea3',\n ];\n const AAVE_WALLET = '0x5a9aaA78B379ec19beb9E44CCe12697d1894f396';\n const SOL_WALLET = 'Fq1F49Vx38f8h62SSRCQpGYPxPEtarY5NZ5GhrFVnrfW';\n\n // ── Contracts ────────────────────────────────────────────────────\n // AAVE V4 — Hub-and-Spoke (replaces single AAVE_POOL from V3)\n const MAIN_SPOKE     = '0x94e7A5dCbE816e498b89aB752661904E2F56c485'; // WETH + USDT supply + USDC borrow\n const BLUECHIP_SPOKE = '0x973a023A77420ba610f06b3858aD991Df6d85A08'; // extra WETH tier (if any)\n const V4_SEL         = '0xbf92857c'; // getUserAccountData (V4 retorna struct novo)\n const AAVE_DATA_PROVIDER = '0x7B4EB56E7CD4b454BA8ff71E4518426369a138a3';\n const UNI_NFT = '0x03a520b32C04BF3bEEf7BEb72E919cf822Ed34f1'; // Base NonfungiblePositionManager\n const LP_TOKEN_ID = 5247352; // posição ativa aberta em 03/06/2026\n const USDT_ADDR = '0xdAC17F958D2ee523a2206206994597C13D831ec7';\n const USDC_ADDR = '0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48';\n const WETH_ADDR = '0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2';\n\n // Kamino program ID on Solana\n const KAMINO_PROGRAM = 'KLend2g3cP87fffoy8q1mQqGKjrL9CGMcnvsoBrDgKzX';\n\n // ── Helpers ──────────────────────────────────────────────────────\n const padAddr = a => '000000000000000000000000' + a.slice(2).toLowerCase();\n const padUint = n => BigInt(n).toString(16).padStart(64, '0');\n const decUint = (hex, offset=0) => BigInt('0x' + (hex.slice(2)||'0').slice(offset*64, (offset+1)*64) || '0');\n const decNum = (n, dec) => Number(n) / Math.pow(10, dec);\n const fmt2 = n => '$' + n.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2});\n const fmtK = n => n >= 1000 ? '$' + (n/1000).toFixed(2) + 'K' : fmt2(n);\n const setEl = (id, v) => { const e = document.getElementById(id); if(e) e.textContent = v; };\n const setHtml = (id, v) => { const e = document.getElementById(id); if(e) e.innerHTML = v; };\n const setColor= (id, c) => { const e = document.getElementById(id); if(e) e.style.color = c; };\n\n async function rpc(url, method, params) {\n const r = await fetch(url, {\n method: 'POST',\n headers: {'Content-Type':'application/json'},\n body: JSON.stringify({id:1, jsonrpc:'2.0', method, params})\n });\n const d = await r.json();\n if (d.error) throw new Error(d.error.message);\n return d.result;\n }\n\n async function ethCall(rpcUrl, to, data) {\n return rpc(rpcUrl, 'eth_call', [{to, data}, 'latest']);\n }\n\n // ── ETH balance for one address ──────────────────────────────────\n async function getEthBalance(addr) {\n const raw = await rpc(ETH_RPC, 'eth_getBalance', [addr, 'latest']);\n return decNum(BigInt(raw), 18);\n }\n\n // ── ERC20 balance ────────────────────────────────────────────────\n async function getERC20(rpcUrl, token, addr, decimals) {\n const data = '0x70a08231' + padAddr(addr);\n const raw = await ethCall(rpcUrl, token, data);\n return decNum(decUint(raw, 0), decimals);\n }\n\n // ── All EVM wallet balances ──────────────────────────────────────\n async function fetchAllEVM() {\n const results = {};\n await Promise.all(EVM_WALLETS.map(async wallet => {\n try {\n const [eth, usdt, usdc, weth] = await Promise.all([\n getEthBalance(wallet).catch(()=>0),\n getERC20(ETH_RPC, USDT_ADDR, wallet, 6).catch(()=>0),\n getERC20(ETH_RPC, USDC_ADDR, wallet, 6).catch(()=>0),\n getERC20(ETH_RPC, WETH_ADDR, wallet, 18).catch(()=>0),\n ]);\n results[wallet] = { eth, usdt, usdc, weth };\n console.log(`[EVM] ${wallet.slice(0,8)}... ETH:${eth.toFixed(4)} USDT:${usdt.toFixed(2)} USDC:${usdc.toFixed(2)}`);\n } catch(e) {\n console.warn(`[EVM] ${wallet.slice(0,8)}... failed:`, e.message);\n results[wallet] = { eth:0, usdt:0, usdc:0, weth:0 };\n }\n }));\n return results;\n }\n\n // ── AAVE V4 ──────────────────────────────────────────────────────\n // V4 struct: [0]=riskPremium(BPS), [1]=avgCF(WAD), [2]=HF(WAD=1e18),\n //            [3]=totalCollateral(/1e26), [4]=totalDebt(/1e35), [5..6]=counts\n async function fetchAave(ethPrice) {\n try {\n const walletData = V4_SEL + padAddr(AAVE_WALLET);\n // Query MAIN_SPOKE (has all positions) + optional BLUECHIP_SPOKE (premium WETH tier)\n const [mainRaw, bcRaw] = await Promise.all([\n   ethCall(ETH_RPC, MAIN_SPOKE, walletData),\n   ethCall(ETH_RPC, BLUECHIP_SPOKE, walletData).catch(() => null)\n ]);\n\n const mainColl = decNum(decUint(mainRaw, 3), 26); // V4: collateral USD /1e26\n const mainDebt = decNum(decUint(mainRaw, 4), 53); // V4: debt USD /1e53 (collateral scale × RAY 1e27)\n const hf       = decNum(decUint(mainRaw, 2), 18); // WAD = 1e18\n\n let bcColl = 0;\n if (bcRaw && bcRaw.length > 10 && bcRaw !== '0x') {\n   const bcHF = decNum(decUint(bcRaw, 2), 18);\n   if (isFinite(bcHF) && bcHF < 1e15) {\n     const bc = decNum(decUint(bcRaw, 3), 26);\n     if (isFinite(bc) && bc > 50) bcColl = bc;\n   }\n }\n const collateral = mainColl + bcColl;\n const debt       = mainDebt;\n\n console.log(`[AAVE V4] coll=$${collateral.toFixed(0)} debt=$${debt.toFixed(2)} HF=${hf.toFixed(2)}`);\n\n // Sanity checks\n if (!isFinite(collateral) || !isFinite(debt) || !isFinite(hf)) {\n   console.warn('[AAVE V4] Sanity: non-finite value, discarding'); return null;\n }\n if (collateral < 100) {\n   console.warn('[AAVE V4] Sanity: collateral $' + collateral.toFixed(2) + ' < $100, discarding'); return null;\n }\n if (hf > 1e15) {\n   console.warn('[AAVE V4] Sanity: HF impossible (' + hf.toExponential(2) + '), discarding'); return null;\n }\n // Com HF > 1, dívida < colateral sempre. Valor acima = erro de escala no parse → descarta.\n if (debt > collateral || debt > 1e7) {\n   console.warn('[AAVE V4] Sanity: debt $' + debt.toExponential(2) + ' > collateral, parse error, discarding'); return null;\n }\n\n // Update AAVE card UI\n setEl('aave-net-worth', fmtK(collateral - debt));\n const hfEl = document.getElementById('aave-hf-metric');\n if (hfEl) {\n   hfEl.textContent = hf.toFixed(2);\n   hfEl.style.color = hf > 2 ? 'var(--green)' : hf > 1.3 ? 'var(--yellow)' : 'var(--red)';\n }\n\n // Store globals for exec bar and other calcs\n window._liveAaveDebt       = debt;\n window._liveAaveCollateral = collateral;\n window._liveAaveHF         = hf;\n\n return { collateral, debt, hf };\n } catch(e) {\n console.warn('[AAVE V4] failed:', e.message);\n return null;\n }\n }\n\n // ── AAVE APYs via ProtocolDataProvider ───────────────────────────\n async function fetchAaveApys() {\n   try {\n     const sel = '0x35ea6a75'; // getReserveData(address)\n     const RAY = 1e27;\n     const [usdtRaw, usdcRaw] = await Promise.all([\n       ethCall(ETH_RPC, AAVE_DATA_PROVIDER, sel + padAddr(USDT_ADDR)).catch(() => null),\n       ethCall(ETH_RPC, AAVE_DATA_PROVIDER, sel + padAddr(USDC_ADDR)).catch(() => null),\n     ]);\n     if (usdtRaw) {\n       const supplyRate = Number(decUint(usdtRaw, 5)) / RAY * 100;\n       if (supplyRate > 0 && supplyRate < 50) window._liveAaveUsdtApy = supplyRate;\n     }\n     if (usdcRaw) {\n       const borrowRate = Number(decUint(usdcRaw, 6)) / RAY * 100;\n       if (borrowRate > 0 && borrowRate < 50) window._liveAaveBorrowApy = borrowRate;\n     }\n     console.log(`[AAVE APY] USDT supply: ${(window._liveAaveUsdtApy||0).toFixed(2)}%, USDC borrow: ${(window._liveAaveBorrowApy||0).toFixed(2)}%`);\n   } catch(e) {\n     console.warn('[AAVE APY] failed:', e.message);\n   }\n }\n\n // ── Uniswap V3 position ──────────────────────────────────────────\n async function fetchUniswapLP() {\n try {\n const data = '0x99fbab88' + padUint(LP_TOKEN_ID);\n const raw = await ethCall(BASE_RPC, UNI_NFT, data);\n const liquidity = decUint(raw, 7);\n const isActive = liquidity > 0n;\n console.log(`[UNI] LP #${LP_TOKEN_ID} liquidity: ${liquidity}, active: ${isActive}`);\n window._liveUniActive = isActive;\n return { liquidity: liquidity.toString(), isActive };\n } catch(e) {\n console.warn('[UNI] failed:', e.message);\n return null;\n }\n }\n\n // ── Solana: native SOL balance ───────────────────────────────────\n async function fetchSolBalance() {\n try {\n const result = await rpc(HELIUS_RPC, 'getBalance', [SOL_WALLET]);\n const sol = result.value / 1e9;\n console.log(`[SOL] Balance: ${sol.toFixed(4)} SOL`);\n window._liveSolWallet = sol;\n return sol;\n } catch(e) {\n console.warn('[SOL] balance failed:', e.message);\n return null;\n }\n }\n\n // ── Solana: all token accounts (for USDS, USDC on Solana) ───────\n async function fetchSolTokens() {\n try {\n const result = await rpc(HELIUS_RPC, 'getTokenAccountsByOwner', [\n SOL_WALLET,\n { programId: 'TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA' },\n { encoding: 'jsonParsed' }\n ]);\n const tokens = {};\n for (const acc of (result.value || [])) {\n const info = acc.account?.data?.parsed?.info;\n if (!info) continue;\n const mint = info.mint;\n const amt = parseFloat(info.tokenAmount?.uiAmountString || '0');\n if (amt > 0.001) {\n tokens[mint] = (tokens[mint] || 0) + amt;\n }\n }\n // Known mints\n const PYUSD_MINT = '2b1kV6DkPAnxd5ixfnxCpjxmKwqjjaYmCZfHsFu24GXo';\n const USDC_SOL = 'EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v';\n console.log('[SOL Tokens] USDS:', tokens[PYUSD_MINT]||0, 'USDC:', tokens[USDC_SOL]||0);\n window._livePyusd = tokens[PYUSD_MINT] || 0;\n window._liveUsdcSol = tokens[USDC_SOL] || 0;\n return tokens;\n } catch(e) {\n console.warn('[SOL Tokens] failed:', e.message);\n return {};\n }\n }\n\n // ── Kamino: fetch position via Kamino API ────────────────────────\n async function fetchKamino() {\n try {\n const MARKET   = '7u3HeHxYDLhnCoErrtycNokbQYbWGzLs6JSDqGAv5PfF';\n const SOL_MINT = 'So11111111111111111111111111111111111111112';\n const USDS_MINT= 'USDSwr9ApdHk5bvJKMjzff41FfuX8bSxdKcR81vTwcA';\n const USDC_MINT= 'EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v';\n\n // Step 1: obligation address + reserves APYs in parallel\n const [oblResp, resResp] = await Promise.all([\n   fetch(`https://api.kamino.finance/kamino-market/${MARKET}/users/${SOL_WALLET}/obligations`),\n   fetch(`https://api.kamino.finance/kamino-market/${MARKET}/reserves/metrics`)\n ]);\n if (!oblResp.ok) throw new Error('Obligations API ' + oblResp.status);\n const obligations = await oblResp.json();\n if (!obligations || !obligations.length) throw new Error('no obligations');\n const obligationAddress = obligations[0].obligationAddress;\n\n // Step 2: loan details\n const loanResp = await fetch(`https://api.kamino.finance/klend/loans/${obligationAddress}`);\n if (!loanResp.ok) throw new Error('Loan API ' + loanResp.status);\n const loan = await loanResp.json();\n\n const deposits = loan.loanInfo?.collateral?.deposits || [];\n const borrows  = loan.loanInfo?.debt?.borrows || [];\n\n let totalDepositUsd = 0, totalBorrowUsd = 0, solQty = 0;\n deposits.forEach(d => {\n   const val = parseFloat(d.tokenValue || 0);\n   totalDepositUsd += val;\n   if (d.tokenMint === SOL_MINT) solQty = parseFloat(d.tokenAmount || 0);\n });\n borrows.forEach(b => { totalBorrowUsd += parseFloat(b.tokenValue || 0); });\n\n // Step 3: APYs from reserves\n if (resResp.ok) {\n   const reserves = await resResp.json();\n   reserves.forEach(r => {\n     const apy = parseFloat(r.supplyApy || 0) * 100;\n     const bapy= parseFloat(r.borrowApy || 0) * 100;\n     if (r.liquidityTokenMint === SOL_MINT  && apy  > 0 && apy  < 50) window._liveKaminoSolApy   = apy;\n     if (r.liquidityTokenMint === USDS_MINT && apy  > 0 && apy  < 50) window._liveKaminoUsdsApy  = apy;\n     if (r.liquidityTokenMint === USDC_MINT && bapy > 0 && bapy < 50) window._liveKaminoBorrowApy = bapy;\n   });\n }\n\n const netValue = totalDepositUsd - totalBorrowUsd;\n const ltv = totalDepositUsd > 0 ? totalBorrowUsd / totalDepositUsd : 0;\n\n console.log(`[Kamino] Deposits: $${totalDepositUsd.toFixed(2)}, Borrows: $${totalBorrowUsd.toFixed(2)}, SOL: ${solQty.toFixed(3)}, LTV: ${(ltv*100).toFixed(1)}%`);\n\n if (totalDepositUsd < 100) { console.warn('[Kamino] Sanity: deposit too low, discarding'); return null; }\n\n window._liveKaminoDebt    = totalBorrowUsd;\n window._liveKaminoDeposit = totalDepositUsd;\n window._liveKaminoNetVal  = netValue;\n window._liveKaminoSol     = solQty;\n window._liveKaminoLtv     = ltv;\n\n // Update Kamino UI\n setEl('kamino-net-val', fmtK(netValue));\n const ltvEl = document.getElementById('kamino-ltv-bar');\n if (ltvEl) {\n   const fill = ltvEl.querySelector('.bar-fill');\n   if (fill) fill.style.width = Math.min(ltv*100, 100).toFixed(1) + '%';\n }\n\n return { totalDepositUsd, totalBorrowUsd, netValue, solQty, ltv };\n } catch(e) {\n console.warn('[Kamino] failed:', e.message);\n window._liveKaminoDebt = window._liveKaminoDebt || 808.77;\n return null;\n }\n }\n\n // ── Compute & display Patrimônio Líquido ─────────────────────────\n function updatePatrimonio(evmData, solBal, ethPrice, solPrice) {\n // In portfolio_analytics, the main netTotal is already computed in renderUI()\n // This function just updates the live globals so renderUI() picks them up\n // and re-triggers a refresh\n\n window._liveEthPrice = ethPrice || window._liveEthPrice || 2079.21;\n window._liveSolPrice = solPrice || window._liveSolPrice || 87.28;\n\n // Re-run fetchPrices to update UI with latest live data\n if (typeof fetchPrices === 'function') {\n fetchPrices().catch(()=>{});\n }\n return null;\n }\n // Re-trigger capital operacional chart if on pools page\n if (typeof getLivePrice === 'function') {\n getLivePrice(['ethereum','solana','cardano','radiant-capital','eigenlayer','polygon-ecosystem-token','zksync','xai-blockchain','zetachain'])\n .then(prices => {\n let total = window._livePatrimonio;\n if (!total) return;\n if (typeof render === 'function') render(total);\n })\n .catch(()=>{});\n }\n\n console.log('[BaroloFetch] Complete ');\n\n // ── Run ───────────────────────────────────────────────────────────\n async function runAll() {\n   const ep = window._liveEthPrice || 2079.21;\n\n   // NOTA: as quantidades de spot (ETH, SOL, USDT, ADA, etc.) vêm EXCLUSIVAMENTE de\n   // WEEKLY_UPDATE.holdings / PORTFOLIO_DATA, sincronizados manualmente com o CoinGecko do Lucas\n   // (a fonte de verdade). Antes havia um fetch on-chain de saldos de carteira que tentava ajustar\n   // o spot, mas as wallets rastreadas não contêm o total (parte fica em CEX/staking/Kamino), o que\n   // inflava/distorcia os números. Removido. O on-chain abaixo é só para DeFi (AAVE/Kamino).\n\n   // Fetch DeFi positions and prices in parallel\n   await Promise.all([\n     fetchAave(ep).catch(e => console.warn('[runAll] fetchAave:', e.message)),\n     fetchAaveApys().catch(e => console.warn('[runAll] fetchAaveApys:', e.message)),\n     fetchKamino().catch(e => console.warn('[runAll] fetchKamino:', e.message)),\n     fetchUniswapLP().catch(() => {}),\n   ]);\n\n   // Fetch prices and re-render\n   if (typeof fetchPrices === 'function') {\n     const ok = await fetchPrices().catch(() => false);\n     if (ok && typeof buildEnriched === 'function' && typeof renderUI === 'function') {\n       try { renderUI(buildEnriched()); } catch(e) {}\n     }\n   }\n   console.log('[BaroloFetch] On-chain ✓');\n }\n\n const delay = document.readyState === 'loading' ? 2500 : 1500;\n if (document.readyState === 'loading') {\n   document.addEventListener('DOMContentLoaded', () => setTimeout(runAll, delay));\n } else {\n   setTimeout(runAll, delay);\n }\n\n // Expose for manual refresh\n window.baroloRefresh = runAll;\n\n})();",
 "portfolioCardano": "(function initCardanoFetch() {\n\n const BF_KEY = 'mainnetUUNZyRnZ6sg9uAvwnprB7vNIu8s7VPKm';\n const BF_URL = 'https://cardano-mainnet.blockfrost.io/api/v0';\n const ADA_ADDR= 'addr1q8cqzzh3t03xvkw7tmzz3jx5nm0spk8ftly7huaj7s6nr4jhy6r0hzw7ygs9ccu6clqqrkm6znuy0ctq737ruk7e72dqkm0a23';\n\n const LOVELACE = 1_000_000; // 1 ADA = 1_000_000 lovelace\n\n async function bf(path) {\n const r = await fetch(`${BF_URL}${path}`, {\n headers: { 'project_id': BF_KEY }\n });\n if (!r.ok) throw new Error(`Blockfrost ${r.status}: ${path}`);\n return r.json();\n }\n\n // ── Fetch ADA wallet balance + stake info ─────────────────────────\n async function fetchCardano() {\n try {\n // 1. Get address info (ADA balance + tokens)\n const addrInfo = await bf(`/addresses/${ADA_ADDR}`);\n const adaWallet = (addrInfo.amount?.find(a => a.unit === 'lovelace')?.quantity || 0) / LOVELACE;\n\n // 2. Get stake address from the payment address\n const stakeAddr = addrInfo.stake_address;\n console.log(`[Cardano] Wallet ADA: ${adaWallet.toFixed(2)}, Stake addr: ${stakeAddr}`);\n\n let stakedAda = 0, rewardsAda = 0, poolName = '—', poolTicker = '—', poolApy = null;\n\n if (stakeAddr) {\n // 3. Get stake account info\n const stakeInfo = await bf(`/accounts/${stakeAddr}`);\n stakedAda = parseInt(stakeInfo.controlled_amount || 0) / LOVELACE;\n rewardsAda = parseInt(stakeInfo.withdrawable_amount || 0) / LOVELACE;\n const poolId = stakeInfo.pool_id;\n\n console.log(`[Cardano] Staked: ${stakedAda.toFixed(2)} ADA, Rewards pending: ${rewardsAda.toFixed(4)} ADA`);\n\n // 4. Get pool info\n if (poolId) {\n try {\n const poolInfo = await bf(`/pools/${poolId}/metadata`);\n poolName = poolInfo.name || poolId.slice(0,12) + '...';\n poolTicker = poolInfo.ticker || '—';\n console.log(`[Cardano] Pool: ${poolTicker} — ${poolName}`);\n } catch(e) { /* pool metadata optional */ }\n\n // 5. Get pool APY from history\n try {\n const poolHistory = await bf(`/pools/${poolId}/history?count=5&order=desc`);\n if (poolHistory?.length > 0) {\n const latest = poolHistory[0];\n // APY ≈ (blocks * avg_reward_per_block / active_stake) * epochs_per_year\n // Simpler: annualize the epoch ROI\n const epochRoi = parseFloat(latest.active_stake) > 0\n ? (parseFloat(latest.rewards) / parseFloat(latest.active_stake)) * 100\n : 0;\n poolApy = (epochRoi * 73).toFixed(2); // ~73 epochs/year\n }\n } catch(e) { /* APY calc optional */ }\n }\n\n // 6. Get recent reward history\n let totalRewardsEarned = 0;\n try {\n const rewardHistory = await bf(`/accounts/${stakeAddr}/rewards?count=20&order=desc`);\n totalRewardsEarned = rewardHistory.reduce((s, r) => s + parseInt(r.amount||0)/LOVELACE, 0);\n console.log(`[Cardano] Last 20 epochs rewards: ${totalRewardsEarned.toFixed(2)} ADA`);\n } catch(e) {}\n\n window._liveAdaStaked = stakedAda;\n window._liveAdaRewards = rewardsAda;\n window._liveAdaPool = { name: poolName, ticker: poolTicker, apy: poolApy };\n window._liveAdaRewardsHistory = totalRewardsEarned;\n }\n\n window._liveAdaWallet = adaWallet;\n\n // Get ADA price from already-fetched CoinGecko data\n const adaPrice = window._livePrices?.cardano?.usd || null;\n\n // Update UI elements\n updateCardanoUI({ adaWallet, stakedAda, rewardsAda, poolName, poolTicker, poolApy, adaPrice });\n\n return { adaWallet, stakedAda, rewardsAda, poolName, poolTicker, poolApy };\n\n } catch(e) {\n console.warn('[Cardano] fetch failed:', e.message);\n return null;\n }\n }\n\n // ── Update UI ────────────────────────────────────────────────────\n function updateCardanoUI({ adaWallet, stakedAda, rewardsAda, poolName, poolTicker, poolApy, adaPrice }) {\n const fmt2 = n => n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n const fmtA = n => n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 4 });\n const setEl = (id, v) => { const e = document.getElementById(id); if(e) e.textContent = v; };\n\n // Wallet ADA\n setEl('ada-wallet-qty', fmtA(adaWallet) + ' ADA');\n setEl('ada-staked-qty', fmtA(stakedAda) + ' ADA');\n setEl('ada-rewards-qty', fmtA(rewardsAda) + ' ADA pendentes');\n setEl('ada-pool-name', poolTicker ? `${poolTicker} — ${poolName}` : poolName);\n setEl('ada-pool-apy', poolApy ? poolApy + '% APY (est.)' : '—');\n\n if (adaPrice) {\n setEl('ada-wallet-usd', '$' + fmt2(adaWallet * adaPrice));\n setEl('ada-staked-usd', '$' + fmt2(stakedAda * adaPrice));\n setEl('ada-rewards-usd', '$' + fmt2(rewardsAda * adaPrice));\n }\n\n // Update the portfolio_analytics ADA row\n const adaRow = document.querySelector('[data-ticker=\"ADA\"]');\n if (adaRow && stakedAda > 0) {\n const qtyEl = adaRow.querySelector('.asset-qty, .col-qty');\n if (qtyEl) qtyEl.textContent = fmtA(stakedAda) + ' ADA';\n }\n\n // Update live indicator\n const liveIndicator = document.getElementById('cardano-live-badge');\n if (liveIndicator) {\n liveIndicator.textContent = '● LIVE';\n liveIndicator.style.color = 'var(--green)';\n }\n\n console.log(`[Cardano UI] Updated: wallet=${adaWallet.toFixed(2)}, staked=${stakedAda.toFixed(2)}, rewards=${rewardsAda.toFixed(4)}, pool=${poolTicker}`);\n }\n\n // ── Build Cardano section HTML (injected into portfolio page) ────\n function buildCardanoSection() {\n const existing = document.getElementById('cardano-stake-section');\n if (existing) return; // already built\n\n // Find where to insert — after ADA row in portfolio or at end of DeFi section\n const target = document.getElementById('cardano-stake-target');\n if (!target) return;\n\n target.innerHTML = `\n <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:6px;padding:14px 16px;margin-top:12px;\">\n <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;\">\n <div style=\"display:flex;align-items:center;gap:8px;\">\n <img src=\"https://coin-images.coingecko.com/coins/images/975/small/cardano.png\" width=\"18\" height=\"18\" style=\"border-radius:50%;\" onerror=\"this.style.opacity='0'\">\n <span style=\"font-family:'Satoshi',serif;font-size:14px;font-weight:600;\">ADA Stake</span>\n <span id=\"cardano-live-badge\" style=\"font-size:8px;color:var(--muted);letter-spacing:1px;\">● —</span>\n </div>\n <span style=\"font-size:9px;color:var(--muted);\" id=\"ada-pool-apy\">—</span>\n </div>\n <div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;\">\n <div style=\"background:var(--surface2);border-radius:4px;padding:8px 10px;\">\n <div style=\"font-size:8px;color:var(--muted);letter-spacing:1.5px;margin-bottom:4px;\">DELEGADO</div>\n <div style=\"font-size:13px;font-weight:600;\" id=\"ada-staked-qty\">375.24 ADA</div>\n <div style=\"font-size:9px;color:var(--muted);\" id=\"ada-staked-usd\">—</div>\n </div>\n <div style=\"background:var(--surface2);border-radius:4px;padding:8px 10px;\">\n <div style=\"font-size:8px;color:var(--muted);letter-spacing:1.5px;margin-bottom:4px;\">REWARDS PENDENTES</div>\n <div style=\"font-size:13px;font-weight:600;color:var(--green);\" id=\"ada-rewards-qty\">— ADA</div>\n <div style=\"font-size:9px;color:var(--muted);\" id=\"ada-rewards-usd\">—</div>\n </div>\n <div style=\"background:var(--surface2);border-radius:4px;padding:8px 10px;\">\n <div style=\"font-size:8px;color:var(--muted);letter-spacing:1.5px;margin-bottom:4px;\">POOL</div>\n <div style=\"font-size:11px;word-break:break-all;\" id=\"ada-pool-name\">—</div>\n </div>\n </div>\n </div>`;\n }\n\n // ── Run ───────────────────────────────────────────────────────────\n async function run() {\n buildCardanoSection();\n await fetchCardano();\n }\n\n // Hook into baroloRefresh\n const _prev = window.baroloRefresh;\n window.baroloRefresh = async function() {\n if (_prev) await _prev();\n await run();\n };\n\n // Auto-run after 3s (after other fetches)\n const delay = document.readyState === 'loading' ? 3500 : 2500;\n if (document.readyState === 'loading') {\n document.addEventListener('DOMContentLoaded', () => setTimeout(run, delay));\n } else {\n setTimeout(run, delay);\n }\n\n})();",
 "poolsWallet": "(function initWalletFetch() {\n\n const ALCHEMY_KEY = 'R_9y5DBqKNR2NapexG8n7';\n const HELIUS_KEY = '76a7f1e6-fac9-4361-a6bb-f7787926c719';\n\n const ETH_RPC = `https://eth-mainnet.g.alchemy.com/v2/${ALCHEMY_KEY}`;\n const BASE_RPC = 'https://mainnet.base.org'; // RPC público — a key Alchemy não tem Base habilitada\n const HELIUS_RPC= `https://mainnet.helius-rpc.com/?api-key=${HELIUS_KEY}`;\n const HELIUS_API= `https://api.helius.xyz/v0`;\n\n // ── Wallets ──────────────────────────────────────────────────────\n const EVM_WALLETS = [\n '0x5Ff957C19A03aF57B5098F3F395A578E394aE4B6',\n '0x5a9aaA78B379ec19beb9E44CCe12697d1894f396', // AAVE\n '0x835a5F686c489023064Edb0EA3A0f4ee54BD77F6',\n '0x8311038D68039f4C3e7237D64f4F2c598fBf4ea3',\n ];\n const AAVE_WALLET = '0x5a9aaA78B379ec19beb9E44CCe12697d1894f396';\n const SOL_WALLET = 'Fq1F49Vx38f8h62SSRCQpGYPxPEtarY5NZ5GhrFVnrfW';\n\n // ── Contracts ────────────────────────────────────────────────────\n // AAVE V4 Hub-and-Spoke contracts\n const MAIN_SPOKE     = '0x94e7A5dCbE816e498b89aB752661904E2F56c485';\n const BLUECHIP_SPOKE = '0x973a023A77420ba610f06b3858aD991Df6d85A08';\n const V4_SEL         = '0xbf92857c'; // getUserAccountData (V4 retorna struct novo)\n const UNI_NFT = '0x03a520b32C04BF3bEEf7BEb72E919cf822Ed34f1'; // Base NonfungiblePositionManager\n const LP_TOKEN_ID = 5247352; // posição ativa aberta em 03/06/2026\n const USDT_ADDR = '0xdAC17F958D2ee523a2206206994597C13D831ec7';\n const USDC_ADDR = '0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48';\n const WETH_ADDR = '0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2';\n\n // Kamino program ID on Solana\n const KAMINO_PROGRAM = 'KLend2g3cP87fffoy8q1mQqGKjrL9CGMcnvsoBrDgKzX';\n\n // ── Helpers ──────────────────────────────────────────────────────\n const padAddr = a => '000000000000000000000000' + a.slice(2).toLowerCase();\n const padUint = n => BigInt(n).toString(16).padStart(64, '0');\n const decUint = (hex, offset=0) => BigInt('0x' + (hex.slice(2)||'0').slice(offset*64, (offset+1)*64) || '0');\n const decNum = (n, dec) => Number(n) / Math.pow(10, dec);\n const fmt2 = n => '$' + n.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2});\n const fmtK = n => n >= 1000 ? '$' + (n/1000).toFixed(2) + 'K' : fmt2(n);\n const setEl = (id, v) => { const e = document.getElementById(id); if(e) e.textContent = v; };\n const setHtml = (id, v) => { const e = document.getElementById(id); if(e) e.innerHTML = v; };\n const setColor= (id, c) => { const e = document.getElementById(id); if(e) e.style.color = c; };\n\n async function rpc(url, method, params) {\n const r = await fetch(url, {\n method: 'POST',\n headers: {'Content-Type':'application/json'},\n body: JSON.stringify({id:1, jsonrpc:'2.0', method, params})\n });\n const d = await r.json();\n if (d.error) throw new Error(d.error.message);\n return d.result;\n }\n\n async function ethCall(rpcUrl, to, data) {\n return rpc(rpcUrl, 'eth_call', [{to, data}, 'latest']);\n }\n\n // ── ETH balance for one address ──────────────────────────────────\n async function getEthBalance(addr) {\n const raw = await rpc(ETH_RPC, 'eth_getBalance', [addr, 'latest']);\n return decNum(BigInt(raw), 18);\n }\n\n // ── ERC20 balance ────────────────────────────────────────────────\n async function getERC20(rpcUrl, token, addr, decimals) {\n const data = '0x70a08231' + padAddr(addr);\n const raw = await ethCall(rpcUrl, token, data);\n return decNum(decUint(raw, 0), decimals);\n }\n\n // ── All EVM wallet balances ──────────────────────────────────────\n async function fetchAllEVM() {\n const results = {};\n await Promise.all(EVM_WALLETS.map(async wallet => {\n try {\n const [eth, usdt, usdc, weth] = await Promise.all([\n getEthBalance(wallet).catch(()=>0),\n getERC20(ETH_RPC, USDT_ADDR, wallet, 6).catch(()=>0),\n getERC20(ETH_RPC, USDC_ADDR, wallet, 6).catch(()=>0),\n getERC20(ETH_RPC, WETH_ADDR, wallet, 18).catch(()=>0),\n ]);\n results[wallet] = { eth, usdt, usdc, weth };\n console.log(`[EVM] ${wallet.slice(0,8)}... ETH:${eth.toFixed(4)} USDT:${usdt.toFixed(2)} USDC:${usdc.toFixed(2)}`);\n } catch(e) {\n console.warn(`[EVM] ${wallet.slice(0,8)}... failed:`, e.message);\n results[wallet] = { eth:0, usdt:0, usdc:0, weth:0 };\n }\n }));\n return results;\n }\n\n // ── AAVE V4 ──────────────────────────────────────────────────────\n // V4 struct: [0]=riskPremium(BPS),[1]=avgCF(WAD),[2]=HF(WAD=1e18),\n //            [3]=totalCollateral(/1e26),[4]=totalDebt(/1e35)\n async function fetchAave(ethPrice) {\n try {\n const walletData = V4_SEL + padAddr(AAVE_WALLET);\n const [mainRaw, bcRaw] = await Promise.all([\n   ethCall(ETH_RPC, MAIN_SPOKE, walletData),\n   ethCall(ETH_RPC, BLUECHIP_SPOKE, walletData).catch(() => null)\n ]);\n\n const mainColl = decNum(decUint(mainRaw, 3), 26);\n const mainDebt = decNum(decUint(mainRaw, 4), 53); // debt scale = collateral 1e26 × RAY 1e27\n const hf       = decNum(decUint(mainRaw, 2), 18);\n\n let bcColl = 0;\n if (bcRaw && bcRaw.length > 10 && bcRaw !== '0x') {\n   const bcHF = decNum(decUint(bcRaw, 2), 18);\n   if (isFinite(bcHF) && bcHF < 1e15) {\n     const bc = decNum(decUint(bcRaw, 3), 26);\n     if (isFinite(bc) && bc > 50) bcColl = bc;\n   }\n }\n const collateral = mainColl + bcColl;\n const debt       = mainDebt;\n\n console.log(`[AAVE V4] coll=$${collateral.toFixed(0)} debt=$${debt.toFixed(2)} HF=${hf.toFixed(2)}`);\n\n if (!isFinite(collateral) || !isFinite(debt) || !isFinite(hf)) {\n   console.warn('[AAVE V4] Sanity: non-finite, discarding'); return null;\n }\n if (collateral < 100) {\n   console.warn('[AAVE V4] Sanity: collateral $' + collateral.toFixed(2) + ' < $100, discarding'); return null;\n }\n if (hf > 1e15) {\n   console.warn('[AAVE V4] Sanity: HF impossible, discarding'); return null;\n }\n // Com HF > 1, dívida < colateral sempre. Valor acima = erro de escala → descarta.\n if (debt > collateral || debt > 1e7) {\n   console.warn('[AAVE V4] Sanity: debt $' + debt.toExponential(2) + ' > collateral, parse error, discarding'); return null;\n }\n\n // Update AAVE card UI\n setEl('aave-net-worth', fmtK(collateral - debt));\n const hfEl = document.getElementById('aave-hf-metric');\n if (hfEl) {\n   hfEl.textContent = hf.toFixed(2);\n   hfEl.style.color = hf > 2 ? 'var(--green)' : hf > 1.3 ? 'var(--yellow)' : 'var(--red)';\n }\n\n // Store globals\n window._liveAaveDebt       = debt;\n window._liveAaveCollateral = collateral;\n window._liveAaveHF         = hf;\n\n return { collateral, debt, hf };\n } catch(e) {\n console.warn('[AAVE V4] failed:', e.message);\n return null;\n }\n }\n\n // ── Uniswap V3 position — composição real via RPC (BASE) ────────\n async function fetchUniswapLP() {\n // ⚠ Pool remontada na Robinhood Chain (WETH/USDG) — fetch on-chain Base desativado; card estático.\n return;\n try {\n const POOL_WETH_USDC = '0x6c561B446416E1A00E8E93E221854d6eA4171372'; // WETH/USDC 0.3% Base (token0=WETH, token1=USDC)\n const Q96 = 2n ** 96n;\n const CAPITAL = 329; // capital de abertura da posição (0.18 WETH @ ETH $1.828 em 03/06/2026)\n\n // 1. positions(tokenId) → ABI slot layout:\n //  [0]=nonce [1]=operator [2]=token0 [3]=token1 [4]=fee\n //  [5]=tickLower [6]=tickUpper [7]=liquidity\n //  [8]=feeGrowth0 [9]=feeGrowth1 [10]=tokensOwed0 [11]=tokensOwed1\n const rawPos = await ethCall(BASE_RPC, UNI_NFT, '0x99fbab88' + padUint(LP_TOKEN_ID));\n\n const liquidity = decUint(rawPos, 7);\n const tokensOwed0 = decUint(rawPos, 10); // WETH (token0, 18 dec na Base)\n const tokensOwed1 = decUint(rawPos, 11); // USDC (token1, 6 dec na Base)\n\n // int24 sign-extension (ticks can be negative)\n const toInt = v => v >= 2n**255n ? Number(v - 2n**256n) : Number(v);\n const tickLower = toInt(decUint(rawPos, 5));\n const tickUpper = toInt(decUint(rawPos, 6));\n\n // 2. slot0() → sqrtPriceX96 + currentTick\n const rawSlot0 = await ethCall(BASE_RPC, POOL_WETH_USDC, '0x3850c7bd');\n const sqrtPriceX96 = decUint(rawSlot0, 0);\n const currentTick = toInt(decUint(rawSlot0, 1));\n\n const isActive = liquidity > 0n;\n const inRange = currentTick >= tickLower && currentTick < tickUpper;\n console.log(`[UNI] liq=${liquidity} ticks=[${tickLower},${tickUpper}] cur=${currentTick} inRange=${inRange}`);\n\n // 3. sqrtPrice Q96 para um tick (float → BigInt)\n function tickToSqrtX96(tick) {\n  const sp = Math.sqrt(Math.pow(1.0001, tick));\n  return BigInt(Math.round(sp * (2 ** 32))) * (2n ** 64n);\n }\n\n const sqrtA = tickToSqrtX96(tickLower);\n const sqrtB = tickToSqrtX96(tickUpper);\n const sqrtP = sqrtPriceX96;\n\n // 4. Calcular quantidades de token0 (WETH) e token1 (USDC) — ordem da Base\n let amount0 = 0n, amount1 = 0n;\n if (currentTick < tickLower) {\n  // Abaixo do range: tudo em WETH (token0)\n  amount0 = liquidity * (sqrtB - sqrtA) * Q96 / sqrtA / sqrtB;\n } else if (currentTick >= tickUpper) {\n  // Acima do range: tudo em USDC (token1)\n  amount1 = liquidity * (sqrtB - sqrtA) / Q96;\n } else {\n  // In-range: mistura dos dois\n  amount0 = liquidity * (sqrtB - sqrtP) * Q96 / sqrtP / sqrtB;\n  amount1 = liquidity * (sqrtP - sqrtA) / Q96;\n }\n\n const weth    = Number(amount0) / 1e18;\n const usdc    = Number(amount1) / 1e6;\n const feeWeth = Number(tokensOwed0) / 1e18;\n const feeUsdc = Number(tokensOwed1) / 1e6;\n\n console.log(`[UNI] USDC:${usdc.toFixed(2)} WETH:${weth.toFixed(5)} fees: ${feeUsdc.toFixed(4)} USDC + ${feeWeth.toFixed(6)} WETH`);\n\n // 5. Preço ETH para converter em USD\n const prices = await getLivePrice(['ethereum']).catch(() => ({ ethereum: { usd: 2100 } }));\n const ethPrice = prices?.ethereum?.usd || 2100;\n\n const wethUsd      = weth * ethPrice;\n const feeWethUsd   = feeWeth * ethPrice;\n const totalPooled  = usdc + wethUsd;\n const totalFees    = feeUsdc + feeWethUsd;\n\n // 6. Atualizar card \"Composição de Tokens\"\n setEl('lp-weth-qty',      weth.toFixed(5) + ' WETH');\n setEl('lp-weth-usd',      '≈ $' + wethUsd.toFixed(2));\n setEl('lp-usdc-qty',      usdc.toFixed(2) + ' USDC');\n setEl('lp-usdc-usd',      '≈ $' + usdc.toFixed(2));\n setEl('lp-fee-weth',      feeWeth.toFixed(6) + ' WETH');\n setEl('lp-fee-weth-usd',  '≈ $' + feeWethUsd.toFixed(2));\n setEl('lp-fee-usdc',      feeUsdc.toFixed(4) + ' USDC');\n setEl('lp-fee-usdc-usd',  '≈ $' + feeUsdc.toFixed(2));\n\n // 7. Atualizar badge IN-RANGE / OUT-OF-RANGE\n const badge = document.querySelector('.badge-green, .badge-warn');\n if (badge) {\n  badge.textContent = inRange ? '● IN-RANGE' : '○ OUT-OF-RANGE';\n  badge.className   = inRange ? 'badge-green' : 'badge-warn';\n }\n\n // Out-of-range notification\n if (!inRange && isActive) {\n  const lastAlert = localStorage.getItem('bc-oor-alert');\n  const now = Date.now();\n  if (!lastAlert || now - parseInt(lastAlert) > 3600000) { // max 1 per hour\n   localStorage.setItem('bc-oor-alert', now.toString());\n   if ('Notification' in window && Notification.permission === 'granted') {\n    new Notification('⚠️ Barolo Capital — Pool OUT OF RANGE', {\n     body: 'WETH/USDC 0.3% saiu do range. Verificar remontagem.',\n     icon: '/favicon.ico'\n    });\n   }\n   // Visual pulse on badge\n   const b = document.querySelector('.badge-warn');\n   if (b) {\n    b.style.animation = 'pulse 1s ease-in-out infinite';\n   }\n  }\n } else if (inRange) {\n  localStorage.removeItem('bc-oor-alert');\n }\n\n // 8. Atualizar LP bar (REFS.usd)\n const openDate = new Date('2026-06-03');\n const DAYS = Math.max(1, Math.floor((Date.now() - openDate.getTime()) / 86400000));\n // PnL = position value + uncollected fees - initial capital\n const pnl      = totalPooled + totalFees - CAPITAL;\n const totalApr = DAYS > 0 ? (pnl / CAPITAL / DAYS * 365 * 100).toFixed(1) + '% / ano' : '—';\n const feeAprPct = totalFees > 0 && DAYS > 0 ? (totalFees / CAPITAL / DAYS * 365 * 100).toFixed(1) + '% fee APR' : DAYS + 'd aberto';\n const dailyFeeStr = totalFees > 0 && DAYS > 0 ? '~$' + (totalFees / DAYS).toFixed(2) + '/dia' : '—';\n REFS.usd = {\n  pooled:    '$' + totalPooled.toFixed(2),\n  pnl:       (pnl >= 0 ? '+' : '-') + '$' + Math.abs(pnl).toFixed(2),\n  roi:       (pnl >= 0 ? '+' : '') + (pnl / CAPITAL * 100).toFixed(2) + '%',\n  apr:       totalApr,\n  feeApr:    feeAprPct,\n  fees:      '$' + totalFees.toFixed(2),\n  il:        '$0.00',\n  gas:       'gas ~$8',\n  dailyFees: dailyFeeStr,\n  pos:       pnl >= 0\n };\n setRef('usd');\n\n window._liveUniActive  = isActive;\n window._liveUniPooled  = totalPooled;\n window._liveLP         = totalPooled;\n try {\n   localStorage.setItem('bc-lp-pooled', JSON.stringify({ value: totalPooled, timestamp: Date.now() }));\n } catch(e) {}\n\n return { liquidity: liquidity.toString(), isActive, usdc, weth, feeUsdc, feeWeth, ethPrice };\n\n } catch(e) {\n console.warn('[UNI] failed:', e.message);\n // Se o outro fetch (fetchUniswapLPData, multi-RPC) já trouxe dados live, não sobrescrever\n if (window._liveLP > 0) return null;\n // Fallback: usar dados do array POOLS (última pool ativa)\n if (typeof POOLS !== 'undefined') {\n  const active = POOLS.find(p => p.status === 'active');\n  if (active) {\n   const days = Math.max(1, Math.floor((Date.now() - new Date('2026-06-03').getTime()) / 86400000));\n   const feeApr = active.fees > 0 ? (active.fees / active.capital / days * 365 * 100).toFixed(1) + '% fee APR' : days + 'd aberto';\n   const totalAprFallback = active.result > 0 ? (active.result / active.capital / days * 365 * 100).toFixed(1) + '% / ano' : '—';\n   REFS.usd = {\n    pooled:    '~$' + active.capital.toFixed(0),\n    pnl:       (active.result >= 0 ? '+' : '') + '$' + Math.abs(active.result).toFixed(0),\n    roi:       (active.result >= 0 ? '+' : '') + (active.result / active.capital * 100).toFixed(1) + '%',\n    apr:       totalAprFallback,\n    feeApr:    feeApr,\n    fees:      '$' + active.fees.toFixed(0),\n    il:        '$' + (active.il || 0).toFixed(0),\n    gas:       'dados locais',\n    dailyFees: active.fees > 0 && days > 0 ? '~$' + (active.fees/days).toFixed(2) + '/dia' : '—',\n    pos:       active.result >= 0\n   };\n   setRef('usd');\n  }\n }\n return null;\n }\n }\n\n // ── Solana: native SOL balance ───────────────────────────────────\n async function fetchSolBalance() {\n try {\n const result = await rpc(HELIUS_RPC, 'getBalance', [SOL_WALLET]);\n const sol = result.value / 1e9;\n console.log(`[SOL] Balance: ${sol.toFixed(4)} SOL`);\n window._liveSolWallet = sol;\n return sol;\n } catch(e) {\n console.warn('[SOL] balance failed:', e.message);\n return null;\n }\n }\n\n // ── Solana: all token accounts (for USDS, USDC on Solana) ───────\n async function fetchSolTokens() {\n try {\n const result = await rpc(HELIUS_RPC, 'getTokenAccountsByOwner', [\n SOL_WALLET,\n { programId: 'TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA' },\n { encoding: 'jsonParsed' }\n ]);\n const tokens = {};\n for (const acc of (result.value || [])) {\n const info = acc.account?.data?.parsed?.info;\n if (!info) continue;\n const mint = info.mint;\n const amt = parseFloat(info.tokenAmount?.uiAmountString || '0');\n if (amt > 0.001) {\n tokens[mint] = (tokens[mint] || 0) + amt;\n }\n }\n // Known mints\n const PYUSD_MINT = '2b1kV6DkPAnxd5ixfnxCpjxmKwqjjaYmCZfHsFu24GXo';\n const USDC_SOL = 'EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v';\n console.log('[SOL Tokens] USDS:', tokens[PYUSD_MINT]||0, 'USDC:', tokens[USDC_SOL]||0);\n window._livePyusd = tokens[PYUSD_MINT] || 0;\n window._liveUsdcSol = tokens[USDC_SOL] || 0;\n return tokens;\n } catch(e) {\n console.warn('[SOL Tokens] failed:', e.message);\n return {};\n }\n }\n\n // ── Kamino: fetch position via Helius DAS ────────────────────────\n async function fetchKamino() {\n try {\n const MARKET   = '7u3HeHxYDLhnCoErrtycNokbQYbWGzLs6JSDqGAv5PfF';\n const SOL_MINT = 'So11111111111111111111111111111111111111112';\n\n const [oblResp] = await Promise.all([\n   fetch(`https://api.kamino.finance/kamino-market/${MARKET}/users/${SOL_WALLET}/obligations`)\n ]);\n if (!oblResp.ok) throw new Error('Obligations API ' + oblResp.status);\n const obligations = await oblResp.json();\n if (!obligations || !obligations.length) throw new Error('no obligations');\n const obligationAddress = obligations[0].obligationAddress;\n\n const loanResp = await fetch(`https://api.kamino.finance/klend/loans/${obligationAddress}`);\n if (!loanResp.ok) throw new Error('Loan API ' + loanResp.status);\n const loan = await loanResp.json();\n\n const deposits = loan.loanInfo?.collateral?.deposits || [];\n const borrows  = loan.loanInfo?.debt?.borrows || [];\n\n let totalDepositUsd = 0, totalBorrowUsd = 0, solQty = 0;\n deposits.forEach(d => {\n   const val = parseFloat(d.tokenValue || 0);\n   totalDepositUsd += val;\n   if (d.tokenMint === SOL_MINT) solQty = parseFloat(d.tokenAmount || 0);\n });\n borrows.forEach(b => { totalBorrowUsd += parseFloat(b.tokenValue || 0); });\n\n const netValue = totalDepositUsd - totalBorrowUsd;\n const ltv = totalDepositUsd > 0 ? totalBorrowUsd / totalDepositUsd : 0;\n\n console.log(`[Kamino] Deposits: $${totalDepositUsd.toFixed(2)}, Borrows: $${totalBorrowUsd.toFixed(2)}, SOL: ${solQty.toFixed(3)}, LTV: ${(ltv*100).toFixed(1)}%`);\n if (totalDepositUsd < 100) { console.warn('[Kamino] Sanity: deposit too low'); return null; }\n\n window._liveKaminoDebt    = totalBorrowUsd;\n window._liveKaminoDeposit = totalDepositUsd;\n window._liveKaminoNetVal  = netValue;\n window._liveKaminoSol     = solQty;\n window._liveKaminoLtv     = ltv;\n\n // Update Kamino UI\n setEl('kamino-net-val', fmtK(netValue));\n const ltvEl = document.getElementById('kamino-ltv-bar');\n if (ltvEl) {\n   const fill = ltvEl.querySelector('.bar-fill');\n   if (fill) fill.style.width = Math.min(ltv*100, 100).toFixed(1) + '%';\n }\n\n return { totalDepositUsd, totalBorrowUsd, netValue, solQty, ltv };\n } catch(e) {\n console.warn('[Kamino] failed:', e.message);\n window._liveKaminoDebt = window._liveKaminoDebt || (window.BAROLO_DATA&&window.BAROLO_DATA.debt.kamino) || 815.97;\n return null;\n }\n }\n\n // ── Compute & display Patrimônio Líquido ─────────────────────────\n function updatePatrimonio(evmData, solBal, ethPrice, solPrice) {\n // Apenas atualiza globals + re-dispara calcCapOp — sem escrever diretamente na UI\n // Evita dupla contagem com saldos EVM que já estão no CoinGecko\n try {\n window._liveEthPrice = ethPrice || window._liveEthPrice || 2079.21;\n window._liveSolPrice = solPrice || window._liveSolPrice || 87.28;\n // Re-trigger via getLivePrice so calcCapOp recalculates with fresh debt values\n if (typeof getLivePrice === 'function') {\n const IDS = ['bitcoin','ethereum','solana','cardano','radiant-capital','eigenlayer',\n 'polygon-ecosystem-token','zksync','xai-blockchain','zetachain'];\n const QTYS = {bitcoin:0.00204156,ethereum:2.37632741,solana:23.31,cardano:375.245,\n 'radiant-capital':7290.46,eigenlayer:153.36298802,'polygon-ecosystem-token':218,\n zksync:876,'xai-blockchain':692.86,zetachain:51.1434};\n getLivePrice(IDS).then(prices => {\n let spot = 0;\n IDS.forEach(id => { spot += (QTYS[id]||0) * (prices?.[id]?.usd || 1); });\n const STABLES = (window.BAROLO_DATA&&window.BAROLO_DATA.stablesTotalUSD) || 1602.52; // fonte: data.js\n const LP_POOLED = window._liveLP || 0; // pool encerrada 03/06/2026\n const DEBT = (window._liveAaveDebt || (window.BAROLO_DATA&&window.BAROLO_DATA.debt.aave) || 754.65) + (window._liveKaminoDebt || (window.BAROLO_DATA&&window.BAROLO_DATA.debt.kamino) || 815.97);\n const total = spot + STABLES + LP_POOLED - DEBT;\n window._livePatrimonio = total;\n console.log(`[Patrimônio] $${total.toFixed(0)} = spot $${spot.toFixed(0)} + stables $${STABLES} + lp $${LP_POOLED.toFixed(0)} − debt $${DEBT.toFixed(0)}`);\n if (typeof render === 'function') render(total);\n // Atualiza Meta 5% display\n const pEl = document.getElementById('capop-patrimonio');\n const rEl = document.getElementById('capop-rec');\n if (pEl) pEl.textContent = '$' + Math.round(total).toLocaleString('en-US');\n if (rEl) rEl.textContent = '$' + Math.round(total * 0.05).toLocaleString('en-US');\n }).catch(()=>{});\n }\n return null;\n } catch(e) {\n console.warn('[Patrimônio] calc failed:', e.message);\n return null;\n }\n }\n async function runAll() {\n  await Promise.all([fetchAllEVM(), fetchKamino(), fetchSolBalance(), fetchSolTokens(), fetchAave(), fetchUniswapLP()]);\n // Re-trigger capital operacional chart if on pools page\n if (typeof getLivePrice === 'function') {\n getLivePrice(['ethereum','solana','cardano','radiant-capital','eigenlayer','polygon-ecosystem-token','zksync','xai-blockchain','zetachain'])\n .then(prices => {\n let total = window._livePatrimonio;\n if (!total) return;\n if (typeof render === 'function') render(total);\n })\n .catch(()=>{});\n }\n\n console.log('[BaroloFetch] Complete ');\n }\n\n // ── Run ───────────────────────────────────────────────────────────\n const delay = document.readyState === 'loading' ? 2500 : 1500;\n if (document.readyState === 'loading') {\n document.addEventListener('DOMContentLoaded', () => setTimeout(runAll, delay));\n } else {\n setTimeout(runAll, delay);\n }\n\n // Auto-refresh a cada 5 minutos\n setInterval(runAll, 5 * 60 * 1000);\n\n // Expose for manual refresh\n window.baroloRefresh = runAll;\n\n})();",
 "poolsCardano": "(function initCardanoFetch() {\n\n const BF_KEY = 'mainnetUUNZyRnZ6sg9uAvwnprB7vNIu8s7VPKm';\n const BF_URL = 'https://cardano-mainnet.blockfrost.io/api/v0';\n const ADA_ADDR= 'addr1q8cqzzh3t03xvkw7tmzz3jx5nm0spk8ftly7huaj7s6nr4jhy6r0hzw7ygs9ccu6clqqrkm6znuy0ctq737ruk7e72dqkm0a23';\n\n const LOVELACE = 1_000_000; // 1 ADA = 1_000_000 lovelace\n\n async function bf(path) {\n const r = await fetch(`${BF_URL}${path}`, {\n headers: { 'project_id': BF_KEY }\n });\n if (!r.ok) throw new Error(`Blockfrost ${r.status}: ${path}`);\n return r.json();\n }\n\n // ── Fetch ADA wallet balance + stake info ─────────────────────────\n async function fetchCardano() {\n try {\n // 1. Get address info (ADA balance + tokens)\n const addrInfo = await bf(`/addresses/${ADA_ADDR}`);\n const adaWallet = (addrInfo.amount?.find(a => a.unit === 'lovelace')?.quantity || 0) / LOVELACE;\n\n // 2. Get stake address from the payment address\n const stakeAddr = addrInfo.stake_address;\n console.log(`[Cardano] Wallet ADA: ${adaWallet.toFixed(2)}, Stake addr: ${stakeAddr}`);\n\n let stakedAda = 0, rewardsAda = 0, poolName = '—', poolTicker = '—', poolApy = null;\n\n if (stakeAddr) {\n // 3. Get stake account info\n const stakeInfo = await bf(`/accounts/${stakeAddr}`);\n stakedAda = parseInt(stakeInfo.controlled_amount || 0) / LOVELACE;\n rewardsAda = parseInt(stakeInfo.withdrawable_amount || 0) / LOVELACE;\n const poolId = stakeInfo.pool_id;\n\n console.log(`[Cardano] Staked: ${stakedAda.toFixed(2)} ADA, Rewards pending: ${rewardsAda.toFixed(4)} ADA`);\n\n // 4. Get pool info\n if (poolId) {\n try {\n const poolInfo = await bf(`/pools/${poolId}/metadata`);\n poolName = poolInfo.name || poolId.slice(0,12) + '...';\n poolTicker = poolInfo.ticker || '—';\n console.log(`[Cardano] Pool: ${poolTicker} — ${poolName}`);\n } catch(e) { /* pool metadata optional */ }\n\n // 5. Get pool APY from history\n try {\n const poolHistory = await bf(`/pools/${poolId}/history?count=5&order=desc`);\n if (poolHistory?.length > 0) {\n const latest = poolHistory[0];\n // APY ≈ (blocks * avg_reward_per_block / active_stake) * epochs_per_year\n // Simpler: annualize the epoch ROI\n const epochRoi = parseFloat(latest.active_stake) > 0\n ? (parseFloat(latest.rewards) / parseFloat(latest.active_stake)) * 100\n : 0;\n poolApy = (epochRoi * 73).toFixed(2); // ~73 epochs/year\n }\n } catch(e) { /* APY calc optional */ }\n }\n\n // 6. Get recent reward history\n let totalRewardsEarned = 0;\n try {\n const rewardHistory = await bf(`/accounts/${stakeAddr}/rewards?count=20&order=desc`);\n totalRewardsEarned = rewardHistory.reduce((s, r) => s + parseInt(r.amount||0)/LOVELACE, 0);\n console.log(`[Cardano] Last 20 epochs rewards: ${totalRewardsEarned.toFixed(2)} ADA`);\n } catch(e) {}\n\n window._liveAdaStaked = stakedAda;\n window._liveAdaRewards = rewardsAda;\n window._liveAdaPool = { name: poolName, ticker: poolTicker, apy: poolApy };\n window._liveAdaRewardsHistory = totalRewardsEarned;\n }\n\n window._liveAdaWallet = adaWallet;\n\n // Get ADA price from already-fetched CoinGecko data\n const adaPrice = window._livePrices?.cardano?.usd || null;\n\n // Update UI elements\n updateCardanoUI({ adaWallet, stakedAda, rewardsAda, poolName, poolTicker, poolApy, adaPrice });\n\n return { adaWallet, stakedAda, rewardsAda, poolName, poolTicker, poolApy };\n\n } catch(e) {\n console.warn('[Cardano] fetch failed:', e.message);\n return null;\n }\n }\n\n // ── Update UI ────────────────────────────────────────────────────\n function updateCardanoUI({ adaWallet, stakedAda, rewardsAda, poolName, poolTicker, poolApy, adaPrice }) {\n const fmt2 = n => n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n const fmtA = n => n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 4 });\n const setEl = (id, v) => { const e = document.getElementById(id); if(e) e.textContent = v; };\n\n // Wallet ADA\n setEl('ada-wallet-qty', fmtA(adaWallet) + ' ADA');\n setEl('ada-staked-qty', fmtA(stakedAda) + ' ADA');\n setEl('ada-rewards-qty', fmtA(rewardsAda) + ' ADA pendentes');\n setEl('ada-pool-name', poolTicker ? `${poolTicker} — ${poolName}` : poolName);\n setEl('ada-pool-apy', poolApy ? poolApy + '% APY (est.)' : '—');\n\n if (adaPrice) {\n setEl('ada-wallet-usd', '$' + fmt2(adaWallet * adaPrice));\n setEl('ada-staked-usd', '$' + fmt2(stakedAda * adaPrice));\n setEl('ada-rewards-usd', '$' + fmt2(rewardsAda * adaPrice));\n }\n\n // Update the portfolio_analytics ADA row\n const adaRow = document.querySelector('[data-ticker=\"ADA\"]');\n if (adaRow && stakedAda > 0) {\n const qtyEl = adaRow.querySelector('.asset-qty, .col-qty');\n if (qtyEl) qtyEl.textContent = fmtA(stakedAda) + ' ADA';\n }\n\n // Update live indicator\n const liveIndicator = document.getElementById('cardano-live-badge');\n if (liveIndicator) {\n liveIndicator.textContent = '● LIVE';\n liveIndicator.style.color = 'var(--green)';\n }\n\n console.log(`[Cardano UI] Updated: wallet=${adaWallet.toFixed(2)}, staked=${stakedAda.toFixed(2)}, rewards=${rewardsAda.toFixed(4)}, pool=${poolTicker}`);\n }\n\n // ── Build Cardano section HTML (injected into portfolio page) ────\n function buildCardanoSection() {\n const existing = document.getElementById('cardano-stake-section');\n if (existing) return; // already built\n\n // Find where to insert — after ADA row in portfolio or at end of DeFi section\n const target = document.getElementById('cardano-stake-target');\n if (!target) return;\n\n target.innerHTML = `\n <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:6px;padding:14px 16px;margin-top:12px;\">\n <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;\">\n <div style=\"display:flex;align-items:center;gap:8px;\">\n <img src=\"https://assets.coingecko.com/coins/images/975/small/cardano.png\" width=\"18\" height=\"18\" style=\"border-radius:50%;\">\n <span style=\"font-family:'Satoshi',serif;font-size:14px;font-weight:600;\">ADA Stake</span>\n <span id=\"cardano-live-badge\" style=\"font-size:8px;color:var(--muted);letter-spacing:1px;\">● —</span>\n </div>\n <span style=\"font-size:9px;color:var(--muted);\" id=\"ada-pool-apy\">—</span>\n </div>\n <div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;\">\n <div style=\"background:var(--surface2);border-radius:4px;padding:8px 10px;\">\n <div style=\"font-size:8px;color:var(--muted);letter-spacing:1.5px;margin-bottom:4px;\">DELEGADO</div>\n <div style=\"font-size:13px;font-weight:600;\" id=\"ada-staked-qty\">375.24 ADA</div>\n <div style=\"font-size:9px;color:var(--muted);\" id=\"ada-staked-usd\">—</div>\n </div>\n <div style=\"background:var(--surface2);border-radius:4px;padding:8px 10px;\">\n <div style=\"font-size:8px;color:var(--muted);letter-spacing:1.5px;margin-bottom:4px;\">REWARDS PENDENTES</div>\n <div style=\"font-size:13px;font-weight:600;color:var(--green);\" id=\"ada-rewards-qty\">— ADA</div>\n <div style=\"font-size:9px;color:var(--muted);\" id=\"ada-rewards-usd\">—</div>\n </div>\n <div style=\"background:var(--surface2);border-radius:4px;padding:8px 10px;\">\n <div style=\"font-size:8px;color:var(--muted);letter-spacing:1.5px;margin-bottom:4px;\">POOL</div>\n <div style=\"font-size:11px;word-break:break-all;\" id=\"ada-pool-name\">—</div>\n </div>\n </div>\n </div>`;\n }\n\n // ── Run ───────────────────────────────────────────────────────────\n async function run() {\n buildCardanoSection();\n await fetchCardano();\n }\n\n // Hook into baroloRefresh\n const _prev = window.baroloRefresh;\n window.baroloRefresh = async function() {\n if (_prev) await _prev();\n await run();\n };\n\n // Auto-run after 3s (after other fetches)\n const delay = document.readyState === 'loading' ? 3500 : 2500;\n if (document.readyState === 'loading') {\n document.addEventListener('DOMContentLoaded', () => setTimeout(run, delay));\n } else {\n setTimeout(run, delay);\n }\n\n})();",
 "poolsPrice": "function fetchTimeout(url, opts, ms) {\n opts = opts || {};\n ms = ms || 7000;\n const timer = new Promise(function(_,rej){ setTimeout(function(){ rej(new Error('timeout')); }, ms); });\n return Promise.race([fetch(url, opts), timer]);\n}\nasync function getLivePrice(ids) {\n const key = ids.join(',');\n if (_priceCache[key] && Date.now() - _priceCache[key].ts < 60000) return _priceCache[key].data;\n try {\n const r = await fetchTimeout(\n 'https://api.coingecko.com/api/v3/simple/price?ids=' + ids.join(',') + '&vs_currencies=usd',\n {}, 8000\n );\n if (!r.ok) throw new Error('CoinGecko HTTP ' + r.status);\n const data = await r.json();\n _priceCache[key] = { ts: Date.now(), data: data };\n return data;\n } catch(e) {\n const data = {};\n for (const id of ids) {\n try {\n const jupId = id === 'ethereum' ? 'ETH' : id === 'solana' ? 'SOL' : id.toUpperCase();\n const r2 = await fetchTimeout('https://price.jup.ag/v6/price?ids=' + jupId, {}, 6000);\n const j = await r2.json();\n if (j && j.data && j.data[jupId] && j.data[jupId].price) data[id] = { usd: j.data[jupId].price };\n } catch(_) {}\n }\n if (Object.keys(data).length) return data;\n return {};\n }\n}"
};
